	public static AnimationDefinition of(PhlegyasAnim anim) {
		return switch (anim) {
			case IDLE -> IDLE;
			case WALK -> WALK;
			case OAR -> OAR;
			case SWEEP -> SWEEP;
			case WAVE -> WAVE;
			case GRAB -> GRAB;
			case STAGGER -> STAGGER;
			case PHASE -> PHASE;
			case INTRO -> INTRO;
			case HURT -> HURT;
			case DEATH -> DEATH;
		};
	}

	/** Every animation, in PhlegyasAnim's order. */
	public static List<AnimationDefinition> all() {
		return Arrays.stream(PhlegyasAnim.values()).map(PhlegyasAnimations::of).toList();
	}
